// Parse search terms configuration
const config = JSON.parse($input.item.json.data);
const strategies = config.search_strategies.filter(s => s.enabled);

// Get current date to determine which strategy to use
const dayOfYear = Math.floor((new Date() - new Date(new Date().getFullYear(), 0, 0)) / 1000 / 60 / 60 / 24);
const strategyIndex = dayOfYear % strategies.length;
const selectedStrategy = strategies[strategyIndex];

// Prepare output
return {
  json: {
    strategy_name: selectedStrategy.name,
    search_terms: selectedStrategy.terms.primary,
    filters: selectedStrategy.filters,
    api_config: config.archive_org_api,
    filtering_criteria: config.filtering_criteria,
    rotation_info: `Day ${dayOfYear}, using strategy ${strategyIndex + 1}/${strategies.length}`
  }
};

// Extract and filter results
const response = $input.item.json;
const docs = response.response?.docs || [];
const filterCriteria = $node['Select Search Strategy'].json.filtering_criteria;

// Filter results based on quality criteria
const filteredDocs = docs.filter(doc => {
  // Check minimum downloads
  if (doc.downloads < filterCriteria.min_downloads) return false;

  // Check if it's text format
  if (!doc.format || !doc.format.includes('PDF') && !doc.format.includes('Text')) return false;

  // Check for excluded keywords
  const titleLower = (doc.title || '').toLowerCase();
  const descLower = (doc.description || '').toLowerCase();
  const textToCheck = titleLower + ' ' + descLower;

  for (const keyword of filterCriteria.exclude_keywords) {
    if (textToCheck.includes(keyword.toLowerCase())) return false;
  }

  return true;
});

// Sort by downloads (quality indicator)
filteredDocs.sort((a, b) => (b.downloads || 0) - (a.downloads || 0));

// Return top results
return filteredDocs.slice(0, 10).map(doc => ({
  json: {
    identifier: doc.identifier,
    title: doc.title,
    creator: doc.creator,
    date: doc.date,
    language: doc.language,
    subject: doc.subject,
    description: doc.description,
    downloads: doc.downloads,
    format: doc.format,
    archive_url: `https://archive.org/details/${doc.identifier}`,
    api_url: `https://archive.org/metadata/${doc.identifier}`,
    discovered_date: new Date().toISOString(),
    search_term: $input.item.json.search_term,
    strategy: $node['Select Search Strategy'].json.strategy_name
  }
}));

// Deduplicate and select best book for today
const allBooks = $input.all();
const uniqueBooks = new Map();

// Deduplicate by identifier
for (const item of allBooks) {
  const id = item.json.identifier;
  if (!uniqueBooks.has(id) || item.json.downloads > uniqueBooks.get(id).json.downloads) {
    uniqueBooks.set(id, item);
  }
}

// Convert to array and sort by downloads
const sortedBooks = Array.from(uniqueBooks.values())
  .sort((a, b) => b.json.downloads - a.json.downloads);

// Check if we've already processed this book (basic check - in production use database)
const today = new Date().toISOString().split('T')[0];
const selectedBook = sortedBooks[0]; // Take top result

if (!selectedBook) {
  throw new Error('No suitable books found today. Try different search terms.');
}

return [
  {
    json: {
      ...selectedBook.json,
      selected_date: today,
      total_candidates: sortedBooks.length,
      status: 'ready_for_processing'
    }
  }
];

// Extract detailed metadata
const metadata = $input.item.json;
const files = metadata.files || [];
const bookInfo = $node['Select Best Book'].json;

// Find PDF or text files
const pdfFiles = files.filter(f => f.format === 'Text PDF' || f.name.endsWith('.pdf'));
const textFiles = files.filter(f => f.format === 'DjVuTXT' || f.name.endsWith('_djvu.txt'));
const ocrFile = files.find(f => f.name.endsWith('_djvu.xml') || f.name.endsWith('_abbyy.gz'));

// Determine best source for text extraction
let textSource = null;
if (textFiles.length > 0) {
  textSource = {
    type: 'text',
    url: `https://archive.org/download/${bookInfo.identifier}/${textFiles[0].name}`,
    filename: textFiles[0].name
  };
} else if (pdfFiles.length > 0) {
  textSource = {
    type: 'pdf',
    url: `https://archive.org/download/${bookInfo.identifier}/${pdfFiles[0].name}`,
    filename: pdfFiles[0].name
  };
} else if (ocrFile) {
  textSource = {
    type: 'ocr',
    url: `https://archive.org/download/${bookInfo.identifier}/${ocrFile.name}`,
    filename: ocrFile.name
  };
}

if (!textSource) {
  throw new Error('No suitable text source found for this book');
}

return {
  json: {
    book_info: bookInfo,
    text_source: textSource,
    total_files: files.length,
    has_ocr: !!ocrFile,
    page_count: metadata.metadata?.imagecount || 'unknown',
    next_step: 'content_processing',
    processing_ready: true
  }
};
